// Package flow refunds orders durably: large refunds wait for finance.
package flow

import (
	"context"
	"errors"
	"fmt"
	"time"

	"refunds/durable"
)

// RefundReq is a refund request for an order, in minor units.
type RefundReq struct {
	Order  int
	Amount int
}

// Refunded is a paid-out refund.
type Refunded struct {
	Order  int
	Amount int
	At     time.Time
}

// TooLargeError is a refund above the limit.
type TooLargeError struct {
	Amount int
}

func (e *TooLargeError) Error() string { return fmt.Sprintf("refund of %d is too large", e.Amount) }

// ErrDeclined is a refund finance declined.
var ErrDeclined = errors.New("refund declined")

// Decision is what finance answers on a large refund.
type Decision int

const (
	Approve Decision = iota
	Deny
)

// Review is what a human approver is shown.
type Review struct {
	Title   string
	Body    string
	Timeout time.Duration
}

// Approver asks a human and waits for the answer.
type Approver interface {
	Approve(ctx context.Context, r Review) (Decision, error)
}

// Version is the workflow version; bump it when the step sequence changes.
const Version = 1

// Refund is the refund workflow.
type Refund struct {
	Approver Approver
	Now      func() time.Time
}

// Pay pays a refund out; it stands in for a ledger call.
func (w *Refund) Pay(r RefundReq) (Refunded, error) {
	return Refunded{Order: r.Order, Amount: r.Amount, At: w.Now()}, nil
}

// Run refunds r, journaling each step in j.
func (w *Refund) Run(ctx context.Context, j *durable.Journal, r RefundReq) (Refunded, error) {
	if err := j.Check(Version); err != nil {
		return Refunded{}, err
	}
	if r.Amount > 10_000 {
		return Refunded{}, &TooLargeError{r.Amount}
	}
	if r.Amount >= 500 {
		review := Review{
			Title:   fmt.Sprintf("Refund for order %d", r.Order),
			Body:    fmt.Sprintf("Amount %d", r.Amount),
			Timeout: 24 * time.Hour,
		}
		d, err := durable.Step(j, "approve", func() (Decision, error) { return w.Approver.Approve(ctx, review) })
		if err != nil {
			return Refunded{}, err
		}
		if d == Deny {
			return Refunded{}, ErrDeclined
		}
	}
	return durable.Step(j, "pay", func() (Refunded, error) { return w.Pay(r) })
}

package flow

import (
	"context"
	"errors"
	"testing"
	"time"

	"refunds/durable"
)

type fakeClock struct{ t time.Time }

func (c *fakeClock) now() time.Time          { return c.t }
func (c *fakeClock) advance(d time.Duration) { c.t = c.t.Add(d) }

// script answers approvals in order and remembers what it was asked.
type script struct {
	answers []Decision
	asked   []Review
}

func (s *script) Approve(ctx context.Context, r Review) (Decision, error) {
	s.asked = append(s.asked, r)
	if len(s.answers) == 0 {
		return 0, errors.New("no scripted answer")
	}
	d := s.answers[0]
	s.answers = s.answers[1:]
	return d, nil
}

// newFake is a refund workflow on a fake clock answering approvals from
// answers.
func newFake(answers ...Decision) (*Refund, *script, *fakeClock) {
	s := &script{answers: answers}
	c := &fakeClock{time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)}
	return &Refund{Approver: s, Now: c.now}, s, c
}

func run(w *Refund, r RefundReq) (Refunded, error) {
	return w.Run(context.Background(), durable.New(Version), r)
}

func TestASmallRefundPaysWithoutAsking(t *testing.T) {
	w, approvals, _ := newFake()
	p, err := run(w, RefundReq{Order: 1, Amount: 120})
	if err != nil || p.Amount != 120 {
		t.Errorf("Run = %+v, %v; want 120", p, err)
	}
	if len(approvals.asked) != 0 {
		t.Errorf("asked %d approvals, want none", len(approvals.asked))
	}
}

func TestALargeRefundWaitsForFinanceAndReplaysFromItsJournal(t *testing.T) {
	w, approvals, clock := newFake(Approve)
	req := RefundReq{Order: 2, Amount: 900}
	j := durable.New(Version)
	p, err := w.Run(context.Background(), j, req)
	if err != nil || p.Amount != 900 {
		t.Fatalf("Run = %+v, %v; want 900", p, err)
	}
	if len(j.Events) != 2 {
		t.Errorf("journal has %d steps, want 2", len(j.Events))
	}
	clock.advance(time.Hour)
	again, err := w.Run(context.Background(), j.Replay(), req)
	if err != nil || again.Order != p.Order || again.Amount != p.Amount || !again.At.Equal(p.At) {
		t.Errorf("replay = %+v, %v; want %+v", again, err, p)
	}
	if len(approvals.asked) != 1 {
		t.Errorf("asked %d approvals, want 1", len(approvals.asked))
	}
}

func TestFinanceCanDecline(t *testing.T) {
	w, _, _ := newFake(Deny)
	if _, err := run(w, RefundReq{Order: 3, Amount: 5_000}); !errors.Is(err, ErrDeclined) {
		t.Errorf("err = %v, want ErrDeclined", err)
	}
}

func TestAHistoryThatDoesNotMatchTheRunIsAReplayError(t *testing.T) {
	w, approvals, _ := newFake(Approve)
	small := durable.New(Version)
	if _, err := w.Run(context.Background(), small, RefundReq{Order: 4, Amount: 100}); err != nil {
		t.Fatal(err)
	}
	_, err := w.Run(context.Background(), small.Replay(), RefundReq{Order: 4, Amount: 900})
	if !errors.Is(err, durable.ErrReplay) {
		t.Errorf("err = %v, want ErrReplay", err)
	}
	if len(approvals.asked) != 0 {
		t.Errorf("asked %d approvals, want none", len(approvals.asked))
	}
}

// Package durable journals the steps of a workflow run so a run can be
// resumed or replayed from its history without repeating its side effects.
package durable

import (
	"encoding/json"
	"errors"
	"fmt"
)

// ErrReplay is a history that does not match the run replaying it.
var ErrReplay = errors.New("history does not match the run")

// Event is one completed step of a run.
type Event struct {
	Step   string
	Result json.RawMessage
}

// Journal is the history of one run: the workflow version it was recorded
// under and its completed steps.
type Journal struct {
	Version int
	Events  []Event
	next    int
}

// New is an empty journal for a run of the given workflow version.
func New(version int) *Journal { return &Journal{Version: version} }

// Replay is a copy of j that replays its history from the first step.
func (j *Journal) Replay() *Journal {
	return &Journal{Version: j.Version, Events: append([]Event(nil), j.Events...)}
}

// Check fails with ErrReplay when j was recorded under another version.
func (j *Journal) Check(version int) error {
	if j.Version != version {
		return fmt.Errorf("%w: recorded by version %d, running version %d", ErrReplay, j.Version, version)
	}
	return nil
}

// Step runs f as the next step of the run named name and records its
// result. When the history already holds that step, its recorded result
// is returned and f does not run. A failed step is not recorded.
func Step[T any](j *Journal, name string, f func() (T, error)) (T, error) {
	var v T
	if j.next < len(j.Events) {
		e := j.Events[j.next]
		if e.Step != name {
			return v, fmt.Errorf("%w: step %d is %q in the history, %q in the run", ErrReplay, j.next+1, e.Step, name)
		}
		j.next++
		err := json.Unmarshal(e.Result, &v)
		return v, err
	}
	v, err := f()
	if err != nil {
		return v, err
	}
	b, err := json.Marshal(v)
	if err != nil {
		return v, err
	}
	j.Events = append(j.Events, Event{Step: name, Result: b})
	j.next++
	return v, nil
}
